//! THE GATE: end-to-end reproduction of
//! `reference/vectors/11-12/fib_ligerito_test.json` (generated by
//! `reference/gen_vectors_11_12.py` from the Python prover): build
//! the vk from the vector's program inputs exactly as the generator
//! does, prove, and assert vk bytes, vk digest, instance bytes and
//! the full proof bytes equal the vector's.

use std::collections::BTreeMap;
use std::path::PathBuf;

use om_elf::Params;
use om_format::{PcsMode, PcsProfile, encode_instance, encode_proof, encode_vk};
use om_prover::{Derived, keygen, prove_instance};
use om_transcript::Hasher;
use serde_json::Value;

fn hex_bytes(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd hex");
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).expect("hex digit"))
        .collect()
}

fn to_hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

#[test]
fn fib_ligerito_test_vector_byte_for_byte() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../reference/vectors/11-12/fib_ligerito_test.json");
    let v: Value =
        serde_json::from_slice(&std::fs::read(&path).expect("read vector")).expect("parse vector");

    // Build the vk from the vector's program inputs, as
    // gen_vectors_11_12.py does: keygen(code, entry, {}, AP,
    // pcs="ligerito", pcs_profile="test", pcs_t=8) with AP from the
    // vector's `abi` block (hash profile defaults to sha256).
    let code: BTreeMap<u64, u32> = v["program"]["code"]
        .as_object()
        .expect("code object")
        .iter()
        .map(|(k, w)| {
            (
                u64::from_str_radix(k, 16).expect("pc hex"),
                u32::from_str_radix(w.as_str().expect("word hex"), 16).expect("word hex"),
            )
        })
        .collect();
    let entry = u64::from_str_radix(v["program"]["entry_pc"].as_str().expect("entry hex"), 16)
        .expect("entry hex");
    let abi = Params {
        ram_log_words: v["abi"]["A"].as_u64().expect("A") as u32,
        input_log_words: v["abi"]["I"].as_u64().expect("I") as u32,
        output_log_words: v["abi"]["O"].as_u64().expect("O") as u32,
        max_code_words: v["abi"]["max_code"].as_u64().expect("max_code"),
        hash_profile: Hasher::Sha256,
    };
    assert_eq!(v["pcs"]["mode"], "ligerito");
    assert_eq!(v["pcs"]["profile"], "test");
    let vk = keygen(
        code,
        entry,
        BTreeMap::new(),
        abi,
        PcsMode::Ligerito,
        PcsProfile::Test,
        v["pcs"]["r"].as_u64().expect("r") as u8,
        v["pcs"]["t"].as_u64().expect("t") as u32,
    )
    .expect("keygen");

    assert_eq!(
        to_hex(&encode_vk(&vk)),
        v["vk_hex"].as_str().expect("vk_hex")
    );
    assert_eq!(
        to_hex(&vk.digest()),
        v["vk_digest"].as_str().expect("vk_digest")
    );

    let (inst, proof) = prove_instance(&vk, b"", None).expect("prove");
    assert_eq!(inst.t, v["T"].as_u64().expect("T"));
    assert_eq!(inst.t, 32);
    assert_eq!(inst.exit_code, v["exit_code"].as_u64().expect("exit_code"));
    assert_eq!(
        to_hex(&inst.output),
        v["output_hex"].as_str().expect("output")
    );
    assert_eq!(
        to_hex(&encode_instance(&inst)),
        v["instance_hex"].as_str().expect("instance_hex")
    );

    let blob = encode_proof(&vk, &proof);
    assert_eq!(
        blob.len(),
        v["proof_bytes"].as_u64().expect("proof_bytes") as usize
    );
    assert_eq!(blob, hex_bytes(v["proof_hex"].as_str().expect("proof_hex")));

    // The vector's derived numbers, via the real derivation.
    let derived = Derived::new(&vk);
    let di = derived.instance(inst.t).expect("instance derivation");
    assert_eq!(di.ell, v["ell"].as_u64().expect("ell") as usize);
    assert_eq!(di.ell, 16);
    assert_eq!(
        di.layout.placements.len(),
        v["components"].as_u64().expect("components") as usize
    );
}
